/// <summary>
/// AVA/WEN 2024/04/02   AVA_011641_EDIGLN
/// </summary>
/// <param name = "_ediAddressType">AVAEDIAddressType</param>
/// <param name = "_account">CustAccount</param>
/// <returns>LogisticsPostalAddressRecId</returns>
[SuppressBPWarning('BPCheckParametersModified', 'necessaryModification')]    
public LogisticsPostalAddressRecId findAddressFromEDIAddress(AVAEDIAddressType _ediAddressType, CustAccount _account)
{
    LogisticsLocation   logisticsLocation;
    CustTable           custTable;
    DirPartyLocation    dirPartyLocation;

    if (_ediAddressType == AVAEDIAddressType::Consignee)
    {
        if (this.GLN)
        {
            logisticsLocation   = AVAEDISalesTableImportClass::findLocationByGLN(this.GLN);
            select firstonly custTable 
                join dirPartyLocation where dirPartyLocation.Party == custTable.Party
                && dirPartyLocation.Location == logisticsLocation.RecId;
            if (custTable.AccountNum)
            {
                _account = custTable.AccountNum;
            }
        }
    }

    return next findAddressFromEDIAddress(_ediAddressType, _account);
}
